CREATE TABLE students(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT,department TEXT,cgpa REAL,skills TEXT,projects INTEGER,internships INTEGER,communication INTEGER,aptitude INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE companies(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,role TEXT NOT NULL,package_lpa REAL,required_skills TEXT,min_cgpa REAL,openings INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applications(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,company_id INTEGER NOT NULL,status TEXT DEFAULT 'Applied',applied_at TEXT DEFAULT CURRENT_TIMESTAMP);
